setcpm(54/4)

// The whole piece, played once: two bars as taught, two loosening, sixteen of your own, a slow amen
song("taught@2 loosening@2 own@16 amen@4", "once")
// Steady, then a ritardando over the last four bars
tempomap("0:13.5 20:13.5 24:10")

// The hymn you were taught: four square chords on the organ, two bars each
// The organ's interaural phase is set per section: 0 degrees sits in the centre of your head,
// 90 loosens, 180 spreads all around you and nearly vanishes in mono
hymn: note("<[c3,e3,g3,c4] [f2,c3,a3,c4] [g2,d3,b3,d4] [c3,e3,g3,c4]>").slow(2)
  .s("sawtooth").timbre("organ").iphase(bysec("taught:0 loosening:90 *:180"))
  .lpf(1400).attack(.6).sustain(.9).release(1.5).space("church").gain(.14)

// The pedal stays put, the same in both ears, and lands on G then C in the amen
pedal: note("<c2 f1 g1 c2>").slow(2).s("sawtooth").timbre("organ").lpf(450)
  .attack(.4).sustain(.8).release(1.5).space("church").gain(.2)

// From the fifth bar, a line of your own: lydian, unhurried, a few notes left out
// It plays everywhere except the first two sections: once it arrives, it stays
own: n("<[0 ~ 2 4] [6 ~ 4 ~] [7 ~ 6 4] [2@2 ~@2]>").scale("C:lydian").transpose(12)
  .degradeBy(.2).seed("own").exceptSections("taught loosening")
  .s("triangle").timbre("soft").attack(.01).decay(1.2).sustain(.1).release(1.4)
  .room(.5).gain(.22)

setcpm(60/4)

// The whole piece, played once: the chamber, the voices fading one by one, then stillness
song("chamber@4 fading@10 stillness@10", "once")
tempomap("0:15 20:15 24:12")

// The chamber: the same few words, whispered from every side at once
const slogan = s("whisper*4").syl("<[sha ha sha ha] [ko ta ko ta]>").hpf(800)
  .exceptSections("stillness")

// Each voice has its own place around your head, and each fades out in turn
// fadeout(k, at) lowers the gain over k bars, starting at bar at; none reaches the stillness
left: slogan.azimuth(-90).distance(1.5).gain(.12).fadeout(4, 4)
right: slogan.late(1/8).azimuth(90).distance(1.5).gain(.12).fadeout(4, 6)
behind: slogan.late(1/4).azimuth(180).distance(2).gain(.1).fadeout(4, 8)
above: slogan.late(3/8).elevation(60).distance(2).gain(.1).fadeout(4, 10)

// What is left when they have gone: a still pad in the middle, and your breath
pad: note("<[d3,a3,e4] [b2,f#3,d4]>").slow(4).s("sawtooth").unison(3).detune(.2)
  .lpf(1100).attack(3).sustain(1).release(4).room(.6).gain(.12).fadein(12)
breath: s("pink").slow(2).hpf(300).lpf(900).attack(3).release(4).gain(.04).fadein(12)

setcpm(66/4)

// The whole piece, played once: the old voice insists, the two trade ears, then only yours
song("insist@8 trading@16 yours@8", "once")
tempomap("0:16.5 28:16.5 32:13")

// ild makes the right ear louder; earswap flips the ears on the bars marked 1
// The old voice leans into one ear, flat and insistent, and fades from bar 8 to bar 24
old: note("<[a2 a2 a2 a2] [a2 a2 g2 a2] [a2 a2 a2 a2] [g2 g2 a2 ~]>")
  .s("voice").voicetype("bass").syl("<[must must must must] [no no shud no] [must must must must] [shud shud no ~]>")
  .ild(8).earswap("<0 0 0 1>").mono(1).vglide(.04)
  .attack(.05).release(.3).room(.3).gain(.2).fadeout(16, 8).exceptSections("yours")

// Your own voice leans into the other ear, and on the fourth bar they trade places
// In the last section it no longer leans: ild 0 puts it in the middle, in both ears
yours: note("<[e4@3 d4] [c#4@2 e4@2] [f#4@3 e4] [a4@4]>")
  .s("voice").voicetype("alto").syl("<[i@3 am] [hir@2 _@2] [i@3 am] [fri@4]>")
  .ild(bysec("yours:0 *:8")).earswap("<1 1 1 0>").mono(2).vglide(.1)
  .attack(.1).release(.8).room(.5).gain(.26)

// A centred drone and soft harp chords, the same in both ears: A, F#m, D, E
drone: note("[a1,e2]").slow(4).s("sine").attack(2).sustain(1).release(3).gain(.16)
harp: note("<[a3 c#4 e4 c#4] [f#3 a3 c#4 a3] [d3 f#3 a3 f#3] [e3 g#3 b3 g#3]>")
  .s("triangle").timbre("soft").decay(.5).sustain(0).release(.6).room(.5).gain(.16)

setcpm(50/4)

// The whole piece, played once: one full drift and return, then the start of another
song("drift@16 again@8", "once")
tempomap("0:12.5 20:12.5 24:9")

// One certainty in unison, then the ears drift apart in cents, two bars at a time, and back
// earsh raises the right ear and lowers the left by half the value each
// 0 cents is one point; 3 beats slowly; 8 and 15 shimmer; 30 opens into two views at once
drone: note("[d2,a2,d3]").s("sawtooth").earsh("<0 0 3 3 8 8 15 15 30 30 15 15 8 8 3 3>")
  .lpf(900).attack(1.5).sustain(1).release(1.5).gain(.16)

// A piano in the middle of your head, asking and answering: D, Bm, G, A
piano: note("<[f#4@3 e4] [d4@4] [d4@2 f#4 b4] [a4@4] [b4@3 a4] [g4@2 d4@2] [e4@2 f#4 a4] [a4@4]>")
  .s("triangle").timbre("soft").attack(.005).decay(1.4).sustain(.1).release(1.6)
  .room(.6).gain(.24)

// Low chords holding the key, ending on an open A
chords: note("<[d3,f#3,a3] [b2,d3,f#3] [g2,b2,d3] [a2,c#3,e3]>").slow(2)
  .s("triangle").timbre("soft").attack(1).sustain(.6).release(2).lpf(1000).room(.6).gain(.14)

setcpm(96/4)

// The whole piece, played once: the march, the turn, your own time, and settling
song("march@4 turning@8 own@20 settling@4", "once")
tempomap("0:24 32:24 36:18")

// The march you kept step to: centred, square and loud, fading out over bars 4 to 12
// It plays only in the first two sections and never comes back
march: s("bd ~ bd ~, ~ sd ~ sd, hh*8").gain(.4).fadeout(8, 4).sections("march turning")
drill: note("<c2 g1>").struct("x ~ x ~").s("sawtooth").lpf(600)
  .decay(.2).sustain(.3).release(.1).gain(.3).fadeout(8, 4).sections("march turning")

// Your own rhythm grows from nothing: hand drums placed around you, seeded but free
hands: s("lt*8?0.45, rim*16?0.3").azimuth(rand.range(-150, 150)).distance(2)
  .seed("own-time").room(.3).gain(.3).fadein(12)

// Under about 0.7 ms a delay between the ears moves a sound sideways: the kalimba sways
kalimba: n(irand(6).segment(8)).scale("C:major pentatonic").transpose(12)
  .degradeBy(.4).seed("sway")
  .s("sine").fm(.8).fmh(5.4).decay(.8).sustain(0).release(.8)
  .itd(sine.range(-.6, .6).slow(4)).room(.4).gain(.2).fadein(8)

// A low pulse that never marches: one soft note per bar, centred
root: note("<c2 a1 f1 g1>").s("sine").attack(.3).sustain(.7).release(1).gain(.28)
  .exceptSections("settling")

// Settling: one low C held through the last four bars
home: note("[c2,g2]").slow(4).s("sine").attack(.5).sustain(.8).release(4).gain(.24)
  .sections("settling")

setcpm(60/4)

// The whole piece, played once: listening with a hint, then listening alone
song("listening@16 alone@8", "once")
tempomap("0:15 20:15 24:12")

// A quiet spring nearby and a breeze
spring: s("stream").slow(4).azimuth(-40).distance(3).gain(.16)
breeze: s("wind").slow(8).intensity(.15).gain(.06)

// The same noise feeds both ears, but one ear's noise is phase-shifted in a narrow band
// Neither ear alone hears a tone; only the two together hear the tune between them
tune: s("white*4").dichotic("<[294 370 440 587] [494 440 370 330] [370 440 494 659] [554 440 330 440]>")
  .dichoticq(30).attack(.02).sustain(1).release(.05).gain(.14)

// A quiet hint: the first phrase on a sine, once every four bars, only while listening
hint: note("<[d4 f#4 a4 d5] ~ ~ ~>").s("sine")
  .decay(.3).sustain(.3).release(.2).gain(.08).sections("listening")

// A soft pad holding the key: D, Bm, G, A
pad: note("<[d3,a3,f#4] [b2,f#3,d4] [g2,d3,b3] [a2,e3,c#4]>")
  .s("triangle").timbre("soft").attack(1).sustain(.6).release(2)
  .lpf(1000).room(.6).gain(.12)

setcpm(40/4)

// The whole piece, played once: six steps outward, then the open space
song("opening@6 open@14", "once")
tempomap("0:10 16:10 20:8")

// icorr 1: the same noise in both ears, a narrow point in the middle of your head
// icorr near 0: unrelated noise in each ear, wide and all around you
const air = s("pink").lpf(2500).attack(.5).sustain(1).release(.5).gain(.1)
narrowing: air.icorr("<1 .8 .6 .4 .2 .1>").sections("opening")
wide: air.icorr(.1).sections("open")

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("<g1 g1 eb1 f1>").slow(2).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.26)

// A pad that barely moves, and a bell at each step outward
pad: note("<[g2,d3,bb3] [eb2,bb2,g3]>").slow(4).s("sawtooth").unison(4).detune(.3)
  .attack(4).release(6).lpf(700).room(.8).size(.9).gain(.1)
bell: note("d5").s("sine").fm(2).fmh(2.76)
  .decay(4).sustain(0).release(4).space("hall").gain(.08).sections("opening")

setcpm(44/4)

// The whole piece, played once: the pieces apart, then together
song("apart@8 together@8", "once")
tempomap("0:11 12:11 16:8")

// A 6 Hz binaural beat in the theta range: each ear is detuned by 3 Hz. Keep the volume low
drone: note("<a1 a1 f1 g1>").slow(4).s("sine").binaural(6)
  .attack(4).sustain(1).release(6).gain(.22)

// Slow, breathing choir chords: Am, F, C, G
choir: note("<[a2,e3,c4] [f2,c3,a3] [c3,g3,e4] [g2,d3,b3]>").slow(2)
  .s("choir").syl("<oo ah oh ah>").attack(3).release(4).space("hall").gain(.2)

// Pieces coming back together: earsplit("harmonics") alternates the partials between the ears
// Only in the first section; bysec has no default, so afterwards earsplit stays unset and each ear hears it whole
pad: note("<[a3,c4,e4] [f3,a3,c4] [c4,e4,g4] [g3,b3,d4]>").slow(2)
  .s("sawtooth").earsplit(bysec("apart:harmonics")).lpf(1400)
  .attack(2).sustain(1).release(3).room(.6).gain(.1)

// A stream nearby
stream: s("stream").slow(4).azimuth(60).distance(4).gain(.14)
